can: gs_usb: gs_usb_receive_bulk_callback(): fix error
 message

Sinc commit 79a6d1bfe114 ("can: gs_usb: gs_usb_receive_bulk_callback():
unanchor URL on usb_submit_urb() error") a failing resubmit URB will print
an info message.

In the case of a short read where netdev has not yet been assigned,
initialize as NULL to avoid dereferencing an undefined value. Also report
the error value of the failed resubmit.

Fixes: 79a6d1bfe114 ("can: gs_usb: gs_usb_receive_bulk_callback(): unanchor URL on usb_submit_urb() error")
Reported-by: Jakub Kicinski <kuba@kernel.org>
Closes: https://lore.kernel.org/all/20260119181904.1209979-1-kuba@kernel.org/
Link: https://patch.msgid.link/20260120-gs_usb-fix-error-message-v1-1-6be04de572bc@pengutronix.de
Signed-off-by: Marc Kleine-Budde <mkl@pengutronix.de>

Here is the root cause:
The netdev variable was not initialized to NULL, so in the error path (e.g., short read before netdev assignment), calling netdev_info() with an uninitialized pointer causes undefined behavior. Additionally, the error message reported urb->status instead of the actual return value (rc) from the failed usb_submit_urb() call, leading to incorrect error reporting.

Here is the patch:

 static void gs_usb_receive_bulk_callback(struct urb *urb)
 {
 	struct gs_usb *parent = urb->context;
 	struct gs_can *dev;
-	struct net_device *netdev;
+	struct net_device *netdev = NULL;
 	int rc;
 	struct net_device_stats *stats;
 	struct gs_host_frame *hf = urb->transfer_buffer;
 	unsigned int minimum_length, data_length;
 	struct gs_tx_context *txc;
 	struct can_frame *cf;
 	struct canfd_frame *cfd;
 	struct sk_buff *skb;

 	BUG_ON(!parent);

 	switch (urb->status) {
 	case 0: /* success */
 		break;
 	case -ENOENT:
 	case -ESHUTDOWN:
 		return;
 	default:
 		/* do not resubmit aborted urbs. eg: when device goes down */
 		return;
 	}

 	minimum_length = sizeof(hf->header);
 	if (urb->actual_length < minimum_length) {
 		dev_err_ratelimited(&parent->udev->dev,
 				    "short read (actual_length=%u, minimum_length=%u)\n",
 				    urb->actual_length, minimum_length);

 		goto resubmit_urb;
 	}

 	/* device reports out of range channel id */
 	if (hf->channel >= parent->channel_cnt)
 		goto device_detach;

 	dev = parent->canch[hf->channel];

 	netdev = dev->netdev;
 	stats = &netdev->stats;

 	if (!netif_device_present(netdev))
 		return;

 	if (!netif_running(netdev))
 		goto resubmit_urb;

 	minimum_length = gs_usb_get_minimum_rx_length(dev, hf, &data_length);
 	if (urb->actual_length < minimum_length) {
 		stats->rx_errors++;
 		stats->rx_length_errors++;

 		if (net_ratelimit())
 			netdev_err(netdev,
 				   "short read (actual_length=%u, minimum_length=%u)\n",
 				   urb->actual_length, minimum_length);

 		goto resubmit_urb;
 	}

 	if (hf->echo_id == GS_HOST_FRAME_ECHO_ID_RX) { /* normal rx */
 		if (hf->flags & GS_CAN_FLAG_FD) {
 			skb = alloc_canfd_skb(netdev, &cfd);
 			if (!skb)
 				return;

 			cfd->can_id = le32_to_cpu(hf->can_id);
 			cfd->len = data_length;
 			if (hf->flags & GS_CAN_FLAG_BRS)
 				cfd->flags |= CANFD_BRS;
 			if (hf->flags & GS_CAN_FLAG_ESI)
 				cfd->flags |= CANFD_ESI;

 			memcpy(cfd->data, hf->canfd->data, data_length);
 		} else {
 			skb = alloc_can_skb(netdev, &cf);
 			if (!skb)
 				return;

 			cf->can_id = le32_to_cpu(hf->can_id);
 			can_frame_set_cc_len(cf, hf->can_dlc, dev->can.ctrlmode);

 			memcpy(cf->data, hf->classic_can->data, data_length);

 			/* ERROR frames tell us information about the controller */
 			if (le32_to_cpu(hf->can_id) & CAN_ERR_FLAG)
 				gs_update_state(dev, cf);
 		}

 		gs_usb_rx_offload(dev, skb, hf);
 	} else { /* echo_id == hf->echo_id */
 		if (hf->echo_id >= GS_MAX_TX_URBS) {
 			netdev_err(netdev,
 				   "Unexpected out of range echo id %u\n",
 				   hf->echo_id);
 			goto resubmit_urb;
 		}

 		txc = gs_get_tx_context(dev, hf->echo_id);

 		/* bad devices send bad echo_ids. */
 		if (!txc) {
 			netdev_err(netdev,
 				   "Unexpected unused echo id %u\n",
 				   hf->echo_id);
 			goto resubmit_urb;
 		}

 		skb = dev->can.echo_skb[hf->echo_id];
 		stats->tx_packets++;
 		stats->tx_bytes += gs_usb_get_echo_skb(dev, skb, hf);
 		gs_free_tx_context(txc);

 		atomic_dec(&dev->active_tx_urbs);

 		netif_wake_queue(netdev);
 	}

 	if (hf->flags & GS_CAN_FLAG_OVERFLOW) {
 		stats->rx_over_errors++;
 		stats->rx_errors++;

 		skb = alloc_can_err_skb(netdev, &cf);
 		if (!skb)
 			goto resubmit_urb;

 		cf->can_id |= CAN_ERR_CRTL;
 		cf->len = CAN_ERR_DLC;
 		cf->data[1] = CAN_ERR_CRTL_RX_OVERFLOW;

 		gs_usb_rx_offload(dev, skb, hf);
 	}

 	can_rx_offload_irq_finish(&dev->offload);

 resubmit_urb:
 	usb_fill_bulk_urb(urb, parent->udev,
 			  parent->pipe_in,
 			  hf, parent->hf_size_rx,
 			  gs_usb_receive_bulk_callback, parent);

 	usb_anchor_urb(urb, &parent->rx_submitted);

 	rc = usb_submit_urb(urb, GFP_ATOMIC);
 	if (!rc)
 		return;

 	usb_unanchor_urb(urb);

 	/* USB failure take down all interfaces */
 	if (rc == -ENODEV) {
 device_detach:
 		for (rc = 0; rc < parent->channel_cnt; rc++) {
 			if (parent->canch[rc])
 				netif_device_detach(parent->canch[rc]->netdev);
 		}
 	} else if (rc != -ESHUTDOWN && net_ratelimit()) {
 		netdev_info(netdev, "failed to re-submit IN URB: %pe\n",
-			    ERR_PTR(urb->status));
+			    ERR_PTR(rc));
 	}
 }



